export type Photo = {
  src: string;
  width: number;
  height: number;
  alt?: string;
};

// Thumbnails are generated by `npm run images` next to the full-size file.
export const thumbnail = (src: string) =>
  src.replace("/assets/", "/assets/thumbs/");

export const photoAlt = (photo: Photo, index: number, total: number) =>
  photo.alt ?? `Photo ${index + 1} of ${total}`;
